		// Token: 0x060001DA RID: 474 RVA: 0x0005F710 File Offset: 0x0005D910
		private void onConnectResult(P2PSessionRequest_t pCallback)
		{
			if (SteamAPI.IsSteamRunning() && this.sc.host)
			{
				CSteamID steamIDRemote = pCallback.m_steamIDRemote;
				if (this.sc.lobby.createdLobby.Count > 0)
				{
					CSteamID csteamID = this.sc.lobby.createdLobby[0];
					bool flag = false;
					for (int i = 0; i < SteamMatchmaking.GetNumLobbyMembers(csteamID); i++)
					{
						if (SteamMatchmaking.GetLobbyMemberByIndex(csteamID, i) == steamIDRemote)
						{
							flag = true;
							SteamNetworking.AcceptP2PSessionWithUser(steamIDRemote);
							this.remoteSteamID = steamIDRemote;
							break;
						}
					}
					if (!flag)
					{
						this.ExitNow();
						return;
					}
				}
				else
				{
					this.ExitNow();
				}
			}
		}

