		private void calcPaintTargets()
		{
			this.cycleTotal = 7;
			this.cycle++;
			if (this.cycle > this.cycleTotal)
			{
				this.cycle = 0;
			}
			if (this.cycle == 1)
			{
				if (this.player1Paint.index.Count > 0)
				{
					this.executePlayer1Blood(ref this.quickSkin1, ref this.player1Paint);
					return;
				}
				if (this.localCleanOn)
				{
					this.localClean -= 0.06f;
					if ((double)this.localClean <= 0.02)
					{
						this.localClean = 0f;
						this.localCleanOn = false;
					}
					this.delPlayer1Blood(ref this.quickSkin1, ref this.localClean);
					return;
				}
			}
			if (this.cycle == 3 && !this.remPlayer.isGone)
			{
				if (this.player2Paint.index.Count > 0)
				{
					this.executePlayer2Blood(ref this.quickSkin2, ref this.player2Paint);
					return;
				}
				if (this.remoteCleanOn)
				{
					this.remoteClean -= 0.06f;
					if (this.remoteClean <= 0.02f)
					{
						this.remoteClean = 0f;
						this.remoteCleanOn = false;
					}
					this.delPlayer2Blood(ref this.quickSkin2, ref this.remoteClean);
					return;
				}
			}
			if (this.cycle == 5 && Princess.cuttyCount > 0 && this.princess[0].canvasPaint.index.Count > 0)
			{
				this.princess[0].executeCanvasBlood();
				return;
			}
			if (this.cycle == 7 && Princess.cuttyCount > 0 && this.princess[0].bodyPaint.index.Count > 0)
			{
				this.princess[0].executeTargetBlood();
			}
		}

