		private float DistanceToLine(Vector3 point, Vector3 anchor, Vector3 end, out Vector3 dir)
		{
			Vector3 vector = end - anchor;
			Vector3 vector2 = Vector3.Normalize(vector);
			float num = Vector3.Dot(point - anchor, vector2);
